solution.code:
#include <stdio.h>

int main() {
    int a[] = {5, 10, 15, 20};
    int *p = a;
    int sum = 0;
    for (int i = 0; i < 4; i++) {
        sum += *(p + i);
    }
    printf("sum = %d\n", sum);
    return 0;
}
